// Normalize Sentry / healthchecks / WUD payloads into one shape.
// Pass raw body through for WUD (hermes enrichment reads it downstream).
let src = ($json.query && $json.query.source) || $json.source || 'unknown';
const b = $json.body || $json;

let title = 'event';
let detail = '';
let emoji = '🔵';

if (src === 'sentry' || b.event) {
  emoji = '🟣';
  const e = b.event || b;
  title = `Sentry: ${e.title || e.metadata?.value || b.message || 'issue'}`;
  detail = `project=${b.project_name || b.project || '?'} level=${e.level || '?'}`;
} else if (src === 'healthchecks' || b.check) {
  const status = (b.check && b.check.status) || b.status || '?';
  emoji = status === 'down' ? '🔴' : '🟢';
  title = `Healthchecks: ${(b.check && b.check.name) || b.name || 'check'} is ${status}`;
  detail = `last_ping=${(b.check && b.check.last_ping) || '?'}`;
} else if (src === 'wud' || b.updateAvailable !== undefined || b.result) {
  // WUD's http trigger posts a FLAT payload: { name, image:{ tag:{value} }, result:{ tag } }.
  // It does not append ?source=wud, so detect by shape and set src for IsWUD routing.
  src = 'wud';
  emoji = '🟠';
  const cur = (b.image && b.image.tag && b.image.tag.value) || '?';
  const next = (b.result && b.result.tag) || '?';
  title = `WUD: update for ${b.name || 'container'}`;
  detail = `${cur} → ${next}`;
}

const content = `${emoji} **[${src}]** ${title}\n${detail ? '`' + detail + '`' : ''}`;
return [{ json: { content, source: src, raw: b } }];

// Merge hermes classification into the WUD Discord message.
const base = $('Normalize').first().json;
let classification = '';
try {
  const h = $json;
  if (h && h.urgency && h.reason) {
    const emo = { high: '🔴', medium: '🟠', low: '🟡' }[h.urgency] || '⚪';
    const safe = h.safe_to_schedule === false ? ' ⚠️ hold' : '';
    classification = `\n${emo} **hermes:** ${h.reason}${safe}`;
  }
} catch (e) {}
return [{ json: { content: base.content + classification, source: base.source } }];
